class Solution {
public:
    int total = 0;
    void walk(TreeNode* node, int cur) {
        if (!node) return;
        cur = cur * 2 + node->val;
        if (!node->left && !node->right) total += cur;
        walk(node->left, cur);
        walk(node->right, cur);
    }
    int sumRootToLeaf(TreeNode* root) {
        walk(root, 0);
        return total;
    }
};
